import fs from "node:fs/promises";
import path from "node:path";

const root = process.cwd();
const sourceDir = path.join(root, "lib/pokemon/knowledge/sources");
const outputDir = path.join(root, "lib/pokemon/knowledge");

const header = `// Generated by scripts/generate-pokemon-knowledge.mjs.\n// Source manifests: lib/pokemon/knowledge/sources/*.json.\n// Do not edit this file by hand; update the source manifests and rerun the generator.\n\n`;

async function readJson(name) {
  return JSON.parse(await fs.readFile(path.join(sourceDir, name), "utf8"));
}

function isHexString(value) {
  return typeof value === "string" && /^0x[0-9a-f]+$/i.test(value);
}

function quote(value) {
  return JSON.stringify(value);
}

function formatValue(value, indent = 0) {
  const pad = " ".repeat(indent);
  const childPad = " ".repeat(indent + 2);

  if (isHexString(value)) return value.toLowerCase();
  if (typeof value === "string") return quote(value);
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  if (value === null) return "null";

  if (Array.isArray(value)) {
    if (value.length === 0) return "[]";
    if (value.every((entry) => isHexString(entry))) {
      return `[\n${value.map((entry) => `${childPad}${entry.toLowerCase()},`).join("\n")}\n${pad}]`;
    }
    if (value.every((entry) => typeof entry === "string")) {
      return `[\n${value.map((entry) => `${childPad}${quote(entry)},`).join("\n")}\n${pad}]`;
    }
    return `[\n${value.map((entry) => `${childPad}${formatValue(entry, indent + 2)},`).join("\n")}\n${pad}]`;
  }

  return formatObject(value, indent);
}

function formatObject(object, indent = 0, options = {}) {
  const pad = " ".repeat(indent);
  const childPad = " ".repeat(indent + 2);
  const entries = Object.entries(object).filter(([, value]) => value !== undefined);
  if (entries.length === 0) return "{}";

  return `{\n${entries.map(([key, value]) => {
    const renderedKey = /^[a-zA-Z_$][\w$]*$/.test(key) ? key : quote(key);
    return `${childPad}${renderedKey}: ${formatValue(value, indent + 2)},`;
  }).join("\n")}\n${pad}}${options.satisfies ? ` satisfies ${options.satisfies}` : ""}`;
}

function withSourceReferences(layout) {
  return {
    generation: layout.generation,
    gameProfile: layout.gameProfile,
    source: `__SOURCE__${layout.sourceKey}`,
    pockets: layout.pockets,
  };
}

function withLayoutSourceReferences(layout) {
  return {
    generation: layout.generation,
    gameProfile: layout.gameProfile,
    source: `__SOURCE__${layout.sourceKey}`,
    liveWramSource: layout.liveWramSourceKey ? `__SOURCE__${layout.liveWramSourceKey}` : undefined,
    boxOffsetsSource: layout.boxOffsetsSourceKey ? `__SOURCE__${layout.boxOffsetsSourceKey}` : undefined,
    offsets: layout.offsets,
    boxOffsets: layout.boxOffsets,
    liveWramOffsets: layout.liveWramOffsets,
  };
}

function withGen3LayoutSourceReferences(layout) {
  return {
    generation: layout.generation,
    gameProfile: layout.gameProfile,
    source: `__SOURCE__${layout.sourceKey}`,
    offsets: layout.offsets,
    sectionIds: layout.sectionIds,
    partyCountSize: layout.partyCountSize,
    quantityMask: layout.quantityMask,
    pcBoxCount: layout.pcBoxCount,
    pcBoxCapacity: layout.pcBoxCapacity,
    pcPokemonSize: layout.pcPokemonSize,
    partyPokemonSize: layout.partyPokemonSize,
    boxNameLength: layout.boxNameLength,
  };
}

function renderObjectWithSourceRefs(object, indent = 0, satisfies) {
  const rendered = formatObject(object, indent, satisfies ? { satisfies } : {});
  return rendered.replace(/"__SOURCE__(\w+)"/g, "POKEMON_KNOWLEDGE_SOURCES.$1");
}

function renderProvenance(sources) {
  return `${header}export type PokemonKnowledgeSourceKind = "official" | "pret" | "pokeapi" | "secondary" | "local-fallback";\n\nexport interface PokemonKnowledgeSource {\n  kind: PokemonKnowledgeSourceKind;\n  name: string;\n  url: string;\n  note?: string;\n  repo?: string;\n  path?: string;\n  commit?: string;\n}\n\nexport const POKEMON_KNOWLEDGE_SOURCES = ${formatObject(sources, 0, { satisfies: "Record<string, PokemonKnowledgeSource>" })};\n`;
}

function renderInventoryLayouts(source) {
  const gen1 = withSourceReferences(source.gen1);
  const gen1Yellow = source.gen1Yellow ? withSourceReferences(source.gen1Yellow) : undefined;
  const gen2 = Object.fromEntries(Object.entries(source.gen2).map(([key, layout]) => [key, withSourceReferences(layout)]));
  const gen3 = Object.fromEntries(Object.entries(source.gen3).map(([key, layout]) => [key, withSourceReferences(layout)]));

  const gen1YellowExport = gen1Yellow
    ? `\n\nexport const GEN1_YELLOW_INVENTORY_LAYOUT: InventoryLayout = ${renderObjectWithSourceRefs(gen1Yellow)};`
    : "";

  return `${header}import { POKEMON_KNOWLEDGE_SOURCES, type PokemonKnowledgeSource } from "./provenance";\n\nexport type InventoryEntryFormat = "counted-pairs" | "counted-ids" | "fixed-quantity";\n\nexport interface InventoryPocketLayout {\n  name: string;\n  offset: number;\n  count: number;\n  format: InventoryEntryFormat;\n  pocketLabel?: string;\n  maxCount?: number;\n  itemIdBase?: number;\n  itemIds?: number[];\n  quantityMask?: "none" | "security-key-low16";\n}\n\nexport interface InventoryLayout {\n  generation: 1 | 2 | 3;\n  gameProfile: string;\n  pockets: InventoryPocketLayout[];\n  source: PokemonKnowledgeSource;\n}\n\nexport const GEN1_INVENTORY_LAYOUT: InventoryLayout = ${renderObjectWithSourceRefs(gen1)};${gen1YellowExport}\n\nexport const GEN2_INVENTORY_LAYOUTS = ${renderObjectWithSourceRefs(gen2, 0, "Record<string, InventoryLayout>")};\n\nexport const GEN3_INVENTORY_LAYOUTS = ${renderObjectWithSourceRefs(gen3, 0, "Record<string, InventoryLayout>")};\n`;
}

function renderItemIdRanges(source) {
  const ranges = Object.fromEntries(
    Object.entries(source.ranges).map(([key, range]) => [
      key,
      {
        generation: range.generation,
        label: range.label,
        start: range.start,
        end: range.end,
        source: `__SOURCE__${range.sourceKey}`,
      },
    ])
  );

  return `${header}import { POKEMON_KNOWLEDGE_SOURCES, type PokemonKnowledgeSource } from "./provenance";\n\nexport interface ItemIdRange {\n  generation: 1 | 2 | 3;\n  label: string;\n  start: number;\n  end: number;\n  source: PokemonKnowledgeSource;\n}\n\nexport const ITEM_ID_RANGES = ${renderObjectWithSourceRefs(ranges, 0, "Record<string, ItemIdRange>")};\n\nexport const GEN1_HM_MOVES = ${formatValue(source.gen1HmMoves, 0)} as const;\n\nexport const GEN1_TM_MOVES = ${formatValue(source.gen1TmMoves, 0)} as const;\n\nexport function getGen1MachineItemName(id: number): string | undefined {\n  const hmRange = ITEM_ID_RANGES.gen1Hms;\n  if (id >= hmRange.start && id <= hmRange.end) {\n    const number = id - hmRange.start + 1;\n    return \`HM\${String(number).padStart(2, "0")} \${GEN1_HM_MOVES[number - 1]}\`;\n  }\n\n  const tmRange = ITEM_ID_RANGES.gen1Tms;\n  if (id >= tmRange.start && id <= tmRange.end) {\n    const number = id - tmRange.start + 1;\n    return \`TM\${String(number).padStart(2, "0")} \${GEN1_TM_MOVES[number - 1]}\`;\n  }\n\n  return undefined;\n}\n`;
}

function renderSpeciesIdMaps(source) {
  const gen3 = Object.fromEntries(
    Object.entries(source.gen3).map(([key, mapping]) => [
      key,
      {
        generation: mapping.generation,
        gameProfile: mapping.gameProfile,
        source: `__SOURCE__${mapping.sourceKey}`,
        oldUnownInternalStart: mapping.oldUnownInternalStart,
        oldUnownInternalEnd: mapping.oldUnownInternalEnd,
        oldUnownNational: mapping.oldUnownNational,
        entries: mapping.entries,
      },
    ])
  );

  return `${header}import { POKEMON_KNOWLEDGE_SOURCES, type PokemonKnowledgeSource } from "./provenance";\n\nexport interface SpeciesIdMapEntry {\n  internal: number;\n  national: number;\n}\n\nexport interface SpeciesIdMap {\n  generation: 3;\n  gameProfile: string;\n  source: PokemonKnowledgeSource;\n  oldUnownInternalStart: number;\n  oldUnownInternalEnd: number;\n  oldUnownNational: number;\n  entries: SpeciesIdMapEntry[];\n}\n\nexport const GEN3_SPECIES_ID_MAPS = ${renderObjectWithSourceRefs(gen3, 0, "Record<string, SpeciesIdMap>")};\n\nconst GEN3_INTERNAL_TO_NATIONAL = new Map<number, number>(\n  GEN3_SPECIES_ID_MAPS.emerald.entries.map((entry) => [entry.internal, entry.national])\n);\n\nexport function getGen3NationalSpeciesId(internalSpecies: number): number {\n  const map = GEN3_SPECIES_ID_MAPS.emerald;\n  if (internalSpecies >= map.oldUnownInternalStart && internalSpecies <= map.oldUnownInternalEnd) {\n    return map.oldUnownNational;\n  }\n  return GEN3_INTERNAL_TO_NATIONAL.get(internalSpecies) ?? internalSpecies;\n}\n`;
}

function withEventFlagSourceReferences(layout) {
  return {
    generation: layout.generation,
    gameProfile: layout.gameProfile,
    source: `__SOURCE__${layout.sourceKey}`,
    flagStartOffset: layout.flagStartOffset,
    liveFlagStartOffset: layout.liveFlagStartOffset,
    flagCount: layout.flagCount,
    entries: layout.entries,
  };
}

function renderEventFlags(source) {
  const gen1 = Object.fromEntries(Object.entries(source.gen1).map(([key, layout]) => [key, withEventFlagSourceReferences(layout)]));
  const gen2 = Object.fromEntries(Object.entries(source.gen2).map(([key, layout]) => [key, withEventFlagSourceReferences(layout)]));
  const gen3 = Object.fromEntries(Object.entries(source.gen3 ?? {}).map(([key, layout]) => [key, withEventFlagSourceReferences(layout)]));

  return `${header}import { POKEMON_KNOWLEDGE_SOURCES, type PokemonKnowledgeSource } from "./provenance";\n\nexport type EventFlagImportance = "story" | "unlock" | "optional" | "routine";\n\nexport interface EventFlagDefinition {\n  id: number;\n  key: string;\n  label: string;\n  category: string;\n  importance: EventFlagImportance;\n  important: boolean;\n  note?: string;\n}\n\nexport interface EventFlagLayout {\n  generation: 1 | 2 | 3;\n  gameProfile: string;\n  source: PokemonKnowledgeSource;\n  flagStartOffset?: number;\n  liveFlagStartOffset?: number;\n  flagCount: number;\n  entries: EventFlagDefinition[];\n}\n\nexport const GEN1_EVENT_FLAGS = ${renderObjectWithSourceRefs(gen1, 0, "Record<string, EventFlagLayout>")};\n\nexport const GEN2_EVENT_FLAGS = ${renderObjectWithSourceRefs(gen2, 0, "Record<string, EventFlagLayout>")};\n\nexport const GEN3_EVENT_FLAGS = ${renderObjectWithSourceRefs(gen3, 0, "Record<string, EventFlagLayout>")};\n`;
}

function renderEventGuides(source) {
  const profiles = Object.fromEntries(
    Object.entries(source.profiles ?? {}).map(([profile, data]) => [profile, data.entries ?? {}])
  );

  return `${header}export type GeneratedEventDescriptionKind = "source-symbol" | "source-context";\n\nexport interface GeneratedEventGuide {\n  description?: string;\n  descriptionKind?: GeneratedEventDescriptionKind;\n  steps?: string[];\n  sourceRefs?: string[];\n}\n\nexport const GENERATED_EVENT_GUIDES: Record<string, Record<string, GeneratedEventGuide>> = ${formatObject(profiles)};\n\nexport function getGeneratedEventGuide(profile: string, key: string): GeneratedEventGuide | undefined {\n  return GENERATED_EVENT_GUIDES[profile]?.[key];\n}\n`;
}

function renderSaveLayouts(source) {
  const gen1 = Object.fromEntries(Object.entries(source.gen1).map(([key, layout]) => [key, withLayoutSourceReferences(layout)]));
  const gen2 = Object.fromEntries(Object.entries(source.gen2).map(([key, layout]) => [key, withLayoutSourceReferences(layout)]));
  const gen3 = Object.fromEntries(Object.entries(source.gen3 ?? {}).map(([key, layout]) => [key, withGen3LayoutSourceReferences(layout)]));

  return `${header}import { POKEMON_KNOWLEDGE_SOURCES, type PokemonKnowledgeSource } from "./provenance";\n\nexport interface Gen1SaveLayout {\n  generation: 1;\n  gameProfile: string;\n  source: PokemonKnowledgeSource;\n  liveWramSource?: PokemonKnowledgeSource;\n  boxOffsetsSource?: PokemonKnowledgeSource;\n  offsets: {\n    playerName: number;\n    rivalName: number;\n    money: number;\n    badges: number;\n    currentMap: number;\n    playTimeHours: number;\n    playTimeMinutes: number;\n    playTimeSeconds: number;\n    partyCount: number;\n    partySpecies: number;\n    partyData: number;\n    trainerId: number;\n    pokedexOwned: number;\n    pokedexSeen: number;\n    currentBoxNumber: number;\n    currentBoxData: number;\n  };\n  boxOffsets: number[];\n  liveWramOffsets: Record<string, number>;\n}\n\nexport interface Gen2SaveLayout {\n  generation: 2;\n  gameProfile: string;\n  source: PokemonKnowledgeSource;\n  liveWramSource?: PokemonKnowledgeSource;\n  boxOffsetsSource?: PokemonKnowledgeSource;\n  offsets: {\n    playerGender: number;\n    playerName: number;\n    trainerId: number;\n    money: number;\n    badgesJohto: number;\n    badgesKanto: number;\n    playTime: number;\n    partyCount: number;\n    partySpecies: number;\n    partyData: number;\n    currentMapGroup: number;\n    currentMap: number;\n    currentMapX: number;\n    currentMapY: number;\n    currentBoxNumber: number;\n    boxNames: number;\n    currentBoxData: number;\n  };\n  boxOffsets: number[];\n  liveWramOffsets: Record<string, number>;\n}\n\nexport interface Gen3SaveLayout {\n  generation: 3;\n  gameProfile: string;\n  source: PokemonKnowledgeSource;\n  offsets: {\n    trainerName: number;\n    trainerGender: number;\n    trainerId: number;\n    playTimeHours: number;\n    playTimeMinutes: number;\n    playTimeSeconds: number;\n    playTimeVBlanks?: number;\n    encryptionKey?: number;\n    pokedexMode: number;\n    pokedexNationalMagic: number;\n    location: number;\n    locationMapGroup: number;\n    locationMapNum: number;\n    partyCount: number;\n    party: number;\n    money: number;\n    coins: number;\n    registeredItem: number;\n    pcItems: number;\n    pokedexOwned: number;\n    pokedexSeen: number;\n    pokedexSeen1: number;\n    pokedexSeen2: number;\n    flags: number;\n    badgeFlagStart: number;\n    boxCurrent: number;\n    boxData: number;\n    boxNames: number;\n    boxWallpapers: number;\n  };\n  sectionIds: {\n    trainerInfo: number;\n    teamItems: number;\n    gameState: number;\n    pcBufferStart: number;\n    pcBufferEnd: number;\n  };\n  partyCountSize: 1 | 4;\n  quantityMask: "none" | "security-key-low16";\n  pcBoxCount: number;\n  pcBoxCapacity: number;\n  pcPokemonSize: number;\n  partyPokemonSize: number;\n  boxNameLength: number;\n}\n\nexport const GEN1_SAVE_LAYOUTS = ${renderObjectWithSourceRefs(gen1, 0, "Record<string, Gen1SaveLayout>")};\n\nexport const GEN2_SAVE_LAYOUTS = ${renderObjectWithSourceRefs(gen2, 0, "Record<string, Gen2SaveLayout>")};\n\nexport const GEN3_SAVE_LAYOUTS = ${renderObjectWithSourceRefs(gen3, 0, "Record<string, Gen3SaveLayout>")};\n`;
}

function luaValue(value) {
  if (isHexString(value)) return value.toLowerCase();
  if (typeof value === "number") return `0x${value.toString(16)}`;
  if (typeof value === "string") return quote(value);
  if (Array.isArray(value)) return `{ ${value.map((entry) => luaValue(entry)).join(", ")} }`;
  throw new Error(`Unsupported Lua value: ${value}`);
}

function numericOffset(value, label) {
  if (typeof value === "number") return value;
  if (isHexString(value)) return Number.parseInt(value.slice(2), 16);
  throw new Error(`Invalid numeric offset for ${label}: ${value}`);
}

function assertWramOffset(value, label) {
  const offset = numericOffset(value, label);
  if (offset < 0xc000 || offset > 0xdfff) {
    throw new Error(`${label} must be a WRAM address in 0xc000..0xdfff, got 0x${offset.toString(16)}.`);
  }
}

function assertSaveOffset(value, label) {
  const offset = numericOffset(value, label);
  if (offset < 0x0000 || offset > 0x7fff) {
    throw new Error(`${label} must be a save/SRAM file offset in 0x0000..0x7fff, got 0x${offset.toString(16)}.`);
  }
}

function validateSaveLayouts(saveLayouts) {
  for (const [profile, layout] of Object.entries(saveLayouts.gen1)) {
    assertSaveOffset(layout.offsets.currentBoxData, `gen1.${profile}.offsets.currentBoxData`);

    for (const [field, value] of Object.entries(layout.liveWramOffsets ?? {})) {
      assertWramOffset(value, `gen1.${profile}.liveWramOffsets.${field}`);
    }

    const liveCurrentBox = numericOffset(
      layout.liveWramOffsets.currentBoxData,
      `gen1.${profile}.liveWramOffsets.currentBoxData`
    );
    const saveCurrentBox = numericOffset(
      layout.offsets.currentBoxData,
      `gen1.${profile}.offsets.currentBoxData`
    );
    if (liveCurrentBox === saveCurrentBox) {
      throw new Error(`gen1.${profile} live current box offset must not reuse save/SRAM current box offset.`);
    }
  }

  const redBlueCurrentBox = numericOffset(
    saveLayouts.gen1.redBlue.liveWramOffsets.currentBoxData,
    "gen1.redBlue.liveWramOffsets.currentBoxData"
  );
  if (redBlueCurrentBox !== 0xda80) {
    throw new Error(
      `gen1.redBlue.liveWramOffsets.currentBoxData must stay 0xda80 per DataCrystal Red/Blue RAM map; got 0x${redBlueCurrentBox.toString(16)}.`
    );
  }

  const yellowPartyCount = numericOffset(
    saveLayouts.gen1.yellow.liveWramOffsets.partyCount,
    "gen1.yellow.liveWramOffsets.partyCount"
  );
  if (yellowPartyCount !== 0xd162) {
    throw new Error(
      `gen1.yellow.liveWramOffsets.partyCount must stay 0xd162 for US Yellow; got 0x${yellowPartyCount.toString(16)}.`
    );
  }

  const yellowCurrentBox = numericOffset(
    saveLayouts.gen1.yellow.liveWramOffsets.currentBoxData,
    "gen1.yellow.liveWramOffsets.currentBoxData"
  );
  if (yellowCurrentBox !== 0xda94) {
    throw new Error(
      `gen1.yellow.liveWramOffsets.currentBoxData must stay 0xda94 for US Yellow; got 0x${yellowCurrentBox.toString(16)}.`
    );
  }

  for (const [profile, layout] of Object.entries(saveLayouts.gen2)) {
    assertSaveOffset(layout.offsets.currentBoxData, `gen2.${profile}.offsets.currentBoxData`);
    for (const [field, value] of Object.entries(layout.liveWramOffsets ?? {})) {
      if (field === "pcStorage") {
        assertSaveOffset(value, `gen2.${profile}.liveWramOffsets.${field}`);
      } else {
        assertWramOffset(value, `gen2.${profile}.liveWramOffsets.${field}`);
      }
    }
  }

  for (const [profile, layout] of Object.entries(saveLayouts.gen3 ?? {})) {
    for (const [field, value] of Object.entries(layout.offsets ?? {})) {
      const offset = numericOffset(value, `gen3.${profile}.offsets.${field}`);
      const maxSectionOffset = ["boxCurrent", "boxData", "boxNames", "boxWallpapers"].includes(field)
        ? 9 * 0xff4 - 1
        : 0x7fff;
      if (offset < 0 || offset > maxSectionOffset) {
        throw new Error(
          `gen3.${profile}.offsets.${field} must be in 0x0000..0x${maxSectionOffset.toString(16)}, got 0x${offset.toString(16)}.`
        );
      }
    }

    if (layout.sectionIds.pcBufferStart !== 5 || layout.sectionIds.pcBufferEnd !== 13) {
      throw new Error(`gen3.${profile} PC storage must use Gen 3 save sections 5..13.`);
    }
    if (layout.pcBoxCount !== 14 || layout.pcBoxCapacity !== 30 || layout.pcPokemonSize !== 80) {
      throw new Error(`gen3.${profile} PC geometry must remain 14 boxes x 30 slots x 80 bytes.`);
    }
    if (layout.partyPokemonSize !== 100) {
      throw new Error(`gen3.${profile} party Pokemon size must remain 100 bytes.`);
    }
  }
}

function renderGen2LiveOffsetsLua(saveLayouts, inventoryLayouts, eventFlags) {
  const tmhmPocket = inventoryLayouts.gen2.crystal.pockets.find((pocket) => pocket.name === "TMs/HMs");
  if (!tmhmPocket?.itemIds?.length) {
    throw new Error("Missing Gen 2 TM/HM item ID sequence for live adapter generation.");
  }

  const luaArray = (values) => values.map((value) => `    ${luaValue(value)},`).join("\n");
  const luaProfile = (layout, extra) => {
    const entries = { ...extra, boxOffsets: layout.boxOffsets, ...layout.liveWramOffsets };
    return Object.entries(entries)
      .map(([key, value]) => `      ${key} = ${luaValue(value)},`)
      .join("\n");
  };

  return `-- Generated by scripts/generate-pokemon-knowledge.mjs.\n-- Source manifests: lib/pokemon/knowledge/sources/*.json.\n-- Do not edit this file by hand; update source manifests and rerun the generator.\n\nreturn {\n  machineItemIds = {\n${luaArray(tmhmPocket.itemIds)}\n  },\n  profiles = {\n    crystal = {\n${luaProfile(saveLayouts.gen2.crystal, { key: "crystal", game: "crystal", moneyFormat: "be24", eventFlags: eventFlags.gen2.crystal.liveFlagStartOffset, eventFlagCount: eventFlags.gen2.crystal.flagCount })}\n    },\n    gold_silver = {\n${luaProfile(saveLayouts.gen2.goldSilver, { key: "gold_silver", game: "gold", moneyFormat: "be24", eventFlags: eventFlags.gen2.goldSilver.liveFlagStartOffset, eventFlagCount: eventFlags.gen2.goldSilver.flagCount })}\n    },\n  },\n}\n`;
}

function renderGen1LiveOffsetsLua(saveLayouts, eventFlags) {
  const luaProfile = (layout, extra) => {
    const entries = { ...extra, boxOffsets: layout.boxOffsets, ...layout.liveWramOffsets };
    return Object.entries(entries)
      .map(([key, value]) => `      ${key} = ${luaValue(value)},`)
      .join("\n");
  };

  return `-- Generated by scripts/generate-pokemon-knowledge.mjs.\n-- Source manifests: lib/pokemon/knowledge/sources/*.json.\n-- Do not edit this file by hand; update source manifests and rerun the generator.\n\nreturn {\n  profiles = {\n    red_blue = {\n${luaProfile(saveLayouts.gen1.redBlue, { key: "red_blue", game: "red", moneyFormat: "bcd24", eventFlags: eventFlags.gen1.redBlue.liveFlagStartOffset, eventFlagCount: eventFlags.gen1.redBlue.flagCount })}\n    },\n    yellow = {\n${luaProfile(saveLayouts.gen1.yellow, { key: "yellow", game: "yellow", moneyFormat: "bcd24", eventFlags: eventFlags.gen1.yellow.liveFlagStartOffset, eventFlagCount: eventFlags.gen1.yellow.flagCount })}\n    },\n  },\n}\n`;
}

function renderGen3LiveOffsetsLua(saveLayouts, inventoryLayouts, speciesIdMaps, eventFlags) {
  const luaPocket = (pocket) => {
    const entries = {
      name: pocket.name,
      offset: pocket.offset,
      count: pocket.count,
      quantityMask: pocket.quantityMask ?? "none",
    };
    return `    {\n${Object.entries(entries).map(([key, value]) => `      ${key} = ${luaValue(value)},`).join("\n")}\n    },`;
  };
  const luaProfile = (layout, inventoryLayout, extra) => {
    const entries = {
      ...extra,
      ...layout.offsets,
      ...layout.liveMemory,
      partyCountSize: layout.partyCountSize,
      quantityMask: layout.quantityMask,
      pcBoxCount: layout.pcBoxCount,
      pcBoxCapacity: layout.pcBoxCapacity,
      pcPokemonSize: layout.pcPokemonSize,
      partyPokemonSize: layout.partyPokemonSize,
      boxNameLength: layout.boxNameLength,
    };
    return `    {\n${Object.entries(entries).map(([key, value]) => `      ${key} = ${luaValue(value)},`).join("\n")}\n      pockets = {\n${inventoryLayout.pockets.map(luaPocket).join("\n")}\n      },\n    }`;
  };
  const speciesMap = speciesIdMaps.gen3.emerald;
  const speciesEntries = speciesMap.entries
    .map((entry) => `    [${entry.internal}] = ${entry.national},`)
    .join("\n");

  return `-- Generated by scripts/generate-pokemon-knowledge.mjs.\n-- Source manifests: lib/pokemon/knowledge/sources/*.json.\n-- Do not edit this file by hand; update source manifests and rerun the generator.\n\nreturn {\n  oldUnownInternalStart = ${luaValue(speciesMap.oldUnownInternalStart)},\n  oldUnownInternalEnd = ${luaValue(speciesMap.oldUnownInternalEnd)},\n  oldUnownNational = ${luaValue(speciesMap.oldUnownNational)},\n  internalToNational = {\n${speciesEntries}\n  },\n  profiles = {\n    ruby_sapphire = ${luaProfile(saveLayouts.gen3.rubySapphire, inventoryLayouts.gen3.rubySapphire, { key: "ruby_sapphire", game: "ruby", nationalMagic: 0xda, eventFlagCount: eventFlags.gen3.rubySapphire.flagCount })},\n    emerald = ${luaProfile(saveLayouts.gen3.emerald, inventoryLayouts.gen3.emerald, { key: "emerald", game: "emerald", nationalMagic: 0xda, eventFlagCount: eventFlags.gen3.emerald.flagCount })},\n    fire_red_leaf_green = ${luaProfile(saveLayouts.gen3.fireRedLeafGreen, inventoryLayouts.gen3.fireRedLeafGreen, { key: "fire_red_leaf_green", game: "firered", nationalMagic: 0xb9, eventFlagCount: eventFlags.gen3.fireRedLeafGreen.flagCount })},\n  },\n}\n`;
}

const [provenance, inventoryLayouts, itemIdRanges, saveLayouts, speciesIdMaps, eventFlags, eventGuides] = await Promise.all([
  readJson("provenance.json"),
  readJson("inventory-layouts.json"),
  readJson("item-id-ranges.json"),
  readJson("save-layouts.json"),
  readJson("species-id-maps.json"),
  readJson("event-flags.json"),
  readJson("event-guides.json").catch(() => ({ profiles: {} })),
]);

validateSaveLayouts(saveLayouts);

await fs.writeFile(path.join(outputDir, "provenance.ts"), renderProvenance(provenance));
await fs.writeFile(path.join(outputDir, "inventory-layouts.ts"), renderInventoryLayouts(inventoryLayouts));
await fs.writeFile(path.join(outputDir, "item-id-ranges.ts"), renderItemIdRanges(itemIdRanges));
await fs.writeFile(path.join(outputDir, "species-id-maps.ts"), renderSpeciesIdMaps(speciesIdMaps));
await fs.writeFile(path.join(outputDir, "event-flags.ts"), renderEventFlags(eventFlags));
await fs.writeFile(path.join(outputDir, "event-guides.ts"), renderEventGuides(eventGuides));
await fs.writeFile(path.join(outputDir, "save-layouts.ts"), renderSaveLayouts(saveLayouts));
await fs.mkdir(path.join(root, "live-adapters/generated"), { recursive: true });
await fs.writeFile(
  path.join(root, "live-adapters/generated/gen1-live-offsets.lua"),
  renderGen1LiveOffsetsLua(saveLayouts, eventFlags)
);
await fs.writeFile(
  path.join(root, "live-adapters/generated/gen2-live-offsets.lua"),
  renderGen2LiveOffsetsLua(saveLayouts, inventoryLayouts, eventFlags)
);
await fs.writeFile(
  path.join(root, "live-adapters/generated/gen3-live-offsets.lua"),
  renderGen3LiveOffsetsLua(saveLayouts, inventoryLayouts, speciesIdMaps, eventFlags)
);

console.log("Generated Pokemon knowledge modules.");
